def moyenne(valeurs):
    if len(valeurs) == 0:
        return 0.0
    return round(sum(valeurs) / len(valeurs), 2)

def top(registre, cle, n):
    def score(fiche):
        return fiche[cle]
    return sorted(registre, key=score, reverse=True)[:n]

def compter(registre, cle):
    resultat = {}
    for fiche in registre:
        v = fiche[cle]
        resultat[v] = resultat.get(v, 0) + 1
    return resultat

