def charger(texte):
    lignes = texte.strip().split("\n")
    entetes = lignes[0].split(",")
    registre = []
    for ligne in lignes[1:]:
        valeurs = ligne.split(",")
        fiche = {}
        for i in range(len(entetes)):
            fiche[entetes[i]] = valeurs[i]
        registre.append(fiche)
    return registre

def nettoyer(valeurs):
    resultat = []
    for v in valeurs:
        try:
            resultat.append(int(v))
        except ValueError:
            pass
    return resultat

def rapport(texte):
    lignes = texte.strip().split("\n")
    villages = []
    recoltes = []
    for ligne in lignes[1:]:
        cases = ligne.split(",")
        try:
            r = int(cases[1])
        except ValueError:
            continue
        villages.append(cases[0])
        recoltes.append(r)
    if len(recoltes) == 0:
        return {"villages": 0, "total": 0, "moyenne": 0.0, "meilleur": ""}
    total = sum(recoltes)
    meilleur = villages[recoltes.index(max(recoltes))]
    return {
        "villages": len(recoltes),
        "total": total,
        "moyenne": round(total / len(recoltes), 1),
        "meilleur": meilleur,
    }
